def is_palindrome(s):
    s = s.lower().replace(' ', '')
    return s == s[::-1]

def remove_duplicates(dict_list):
    seen = set()
    result = []
    for d in dict_list:
        key = tuple(sorted(d.items()))
        if key not in seen:
            seen.add(key)
            result.append(d)
    return result

def kth_largest_distinct(nums, k):
    distinct = sorted(set(nums), reverse=True)
    return distinct[k - 1]

import re

def is_anagram(a, b):
    clean = lambda s: sorted(re.findall(r'[a-z0-9]', s.lower()))
    return clean(a) == clean(b)

def merge_sorted_lists(left, right):
    i = j = 0
    merged = []
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

def group_by_length(strings):
    groups = {}
    for s in strings:
        groups.setdefault(len(s), []).append(s)
    return groups
